'use strict'

import resource from '../resource'
import worldManager from '../service/world-manager'
import { TILE_WIDTH, TILES_PER_LINE, TILES_PER_COLUMN, WORLD_MAPS_PER_LINE, WORLD_MAPS_PER_COLUMN } from '../constant'

// The detailed map of the surface on the top menu, an option of the page (not in the ROM, where the map is gray):
// the 16 × 8 screens drawn small, each squeezed into its square of the map, as the ROM does with its dot. Each tile
// is first drawn 8 × 8 pixels, then the whole is reduced smoothly. Drawn once, again when the graphics change
const TILE_PIXELS = 8
const SCREEN_PIXELS = 32

let cache

// The image of the surface (undefined without a page to draw it in)
export function worldMinimap () {
  if (cache?.version === resource.packVersion && cache.maps === worldManager.world) {
    return cache.image
  }
  if (typeof document === 'undefined') {
    return undefined
  }
  const tiles = document.createElement('canvas')
  tiles.width = WORLD_MAPS_PER_LINE * TILES_PER_LINE * TILE_PIXELS
  tiles.height = WORLD_MAPS_PER_COLUMN * TILES_PER_COLUMN * TILE_PIXELS
  const tilesContext = tiles.getContext('2d')
  const ratio = TILE_PIXELS / TILE_WIDTH
  for (const column of worldManager.world) {
    for (const map of column ?? []) {
      for (const tile of map?.tilesIterator() ?? []) {
        tile.sprite?.draw(tilesContext, tile.x * ratio, tile.y * ratio, TILE_PIXELS, TILE_PIXELS)
      }
    }
  }
  const image = document.createElement('canvas')
  image.width = WORLD_MAPS_PER_LINE * SCREEN_PIXELS
  image.height = WORLD_MAPS_PER_COLUMN * SCREEN_PIXELS
  const context = image.getContext('2d')
  context.imageSmoothingEnabled = true
  context.imageSmoothingQuality = 'high'
  context.drawImage(tiles, 0, 0, image.width, image.height)
  cache = { version: resource.packVersion, maps: worldManager.world, image }
  return image
}
