'use strict'

import resource from '../../resource'
import { ENEMY_KEESE_BLUE, ENEMY_KEESE_RED, ENEMY_KEESE_BLACK } from '../../constant'
import { drawImage } from './common'
import { Flyer } from './flyer'

// A bat of the dungeons, measured in the ROM (objects $1B to $1D, bank 4 $8481): it flies as the peahats (see
// flyer.js, the same table of phases $84A4 and the same choices), up to $C0 (0.75 NES pixel a frame), taking off
// as soon as it is out of its cloud, and turns back at the edge of the room. Anything kills it, the boomerang too;
// it takes half a heart from Link
export const KEESES = { [ENEMY_KEESE_BLUE]: 'blue', [ENEMY_KEESE_RED]: 'red', [ENEMY_KEESE_BLACK]: 'black' }
const KEESE = { life: 0, contactDamage: 0.5, maxSpeed: 0xc0 }
const KEESE_CHANCES = { chase: 0x60 / 256, land: 0x20 / 256 }
// The wings beat faster when it flies faster
const FLAP_SPEED_STEPS = 6 * 0xc0

export class Keese extends Flyer {
  constructor (type, x, y, random = Math.random) {
    super(type, x, y, KEESE, KEESE_CHANCES, random)
    this.colour = KEESES[type]
    this.flap = 0
  }

  // Out of its cloud
  start () {
    this.fly()
    this.takeOff()
  }

  // Killed by the boomerang
  stun (link) {
    this.hit(link, { damage: 1 })
  }

  act (map, link) {
    this.flap += this.speed
    super.act(map, link)
  }

  drawBody (context) {
    drawImage(context, resource.getSprite(`keese_${this.colour}_move`), Math.floor(this.flap / FLAP_SPEED_STEPS) % 2, this.x, this.y, this.width, this.height)
  }
}
