'use strict'

// Game clock: game steps, sprite animations, transitions and dialogs are scheduled here
// instead of setInterval / setTimeout, so they all advance (and pause) together.
// Time only moves when tick() is called, once per animation frame.

const MAX_TICK_DELTA = 250 // ms, avoids a burst of catch-up steps after the tab was hidden

class Timer {
  constructor (due, interval, callback, repeat) {
    this.due = due
    this.interval = interval
    this.callback = callback
    this.repeat = repeat
    this.cancelled = false
  }

  cancel () {
    this.cancelled = true
  }
}

class Clock {
  constructor () {
    this.now = 0
    this.paused = false
    this.timers = []
  }

  // Same argument order as setInterval / setTimeout
  repeat (callback, interval) {
    return this.schedule(callback, Math.max(1, interval), true)
  }

  delay (callback, delay) {
    return this.schedule(callback, delay, false)
  }

  schedule (callback, delay, repeat) {
    const timer = new Timer(this.now + delay, delay, callback, repeat)
    this.timers.push(timer)

    return timer
  }

  // Drops every timer (new game, tests): nothing scheduled before fires any more
  reset () {
    for (const timer of this.timers) {
      timer.cancel()
    }
    this.timers = []
    this.paused = false
  }

  pause () {
    this.paused = true
  }

  resume () {
    this.paused = false
  }

  tick (delta) {
    if (this.paused) {
      return
    }

    const target = this.now + Math.min(Math.max(delta, 0), MAX_TICK_DELTA)
    // Fire due timers in chronological order (creation order on ties), as the browser would
    for (;;) {
      this.timers = this.timers.filter(timer => !timer.cancelled)
      let next
      for (const timer of this.timers) {
        if (timer.due <= target && (!next || timer.due < next.due)) {
          next = timer
        }
      }
      if (!next) {
        break
      }
      this.now = next.due
      if (next.repeat) {
        next.due += next.interval
      } else {
        next.cancelled = true
      }
      next.callback()
    }
    this.now = target
  }
}

export { Clock }
export default new Clock()
